import { z } from 'zod';

/**
 * Only the parts of the Feishu event schema this product uses.
 *
 * Feishu's full event model is enormous. Typing all of it would be a maintenance
 * burden for zero benefit — what we need is: who sent it, where, what they said,
 * and whether the bot was addressed. Everything else is passed through untouched
 * so a future feature can read it without a schema change here.
 */
export const FeishuMessageEvent = z.object({
  schema: z.string().optional(),
  /**
   * Feishu has two event generations in the wild. v2 events carry `header`;
   * v1 events (still delivered by some older subscriptions) do not, and put the
   * event type inside `event` instead. Treating header as required would reject
   * every v1 delivery, so it is optional and the idempotency key falls back.
   */
  header: z
    .object({
      event_id: z.string(),
      event_type: z.string(),
      create_time: z.string().optional(),
      token: z.string().optional(),
      tenant_key: z.string().optional(),
    })
    .optional(),
  event: z.object({
    sender: z.object({
      sender_id: z
        .object({
          // Feishu sends `null` for ids that do not apply (e.g. `user_id` on a
          // tenant-level event). `optional()` alone rejects null and silently
          // drops the whole message.
          open_id: z.string().nullish(),
          user_id: z.string().nullish(),
          union_id: z.string().nullish(),
        })
        .optional(),
      sender_type: z.string().optional(),
    }),
    message: z.object({
      message_id: z.string(),
      chat_id: z.string(),
      chat_type: z.enum(['p2p', 'group']),
      message_type: z.string(),
      /**
       * JSON-encoded string for text messages: `{"text":"..."}`. Some SDK
       * transports hand the already-parsed object instead, so accept both.
       */
      content: z.union([z.string(), z.record(z.string(), z.unknown())]),
      mentions: z
        .array(
          z.object({
            key: z.string(),
            name: z.string().optional(),
            /**
             * The event payload uses `{ open_id }`; the message-detail API uses a
             * bare open_id string. Accept both — rejecting one silently drops
             * every group message, which is exactly the bug this product exists
             * to make visible.
             */
            id: z
              .union([z.string(), z.object({ open_id: z.string().nullish() })])
              .optional(),
          }),
        )
        .optional(),
    }),
  }),
});
export type FeishuMessageEvent = z.infer<typeof FeishuMessageEvent>;

export interface NormalisedMessage {
  /** Stable id for idempotency — Feishu retries deliveries. */
  eventId: string;
  messageId: string;
  chatId: string;
  chatType: 'p2p' | 'group';
  senderOpenId: string;
  /** The text with @-mention placeholders removed. This is the agent's prompt. */
  text: string;
  /** True when the message addresses the bot. In a group, ignore everything else. */
  addressedToBot: boolean;
  /** Open ids of everyone mentioned. The gateway compares these to its own bot id. */
  mentionedOpenIds: string[];
  /** Display names of everyone mentioned, for tenants that do not expose open ids. */
  mentionedNames: string[];
}

/**
 * Turn a raw payload into the one shape the gateway acts on.
 *
 * Returns null for events we deliberately ignore (non-text messages, bot senders,
 * unknown event types) rather than throwing: Feishu retries on non-2xx, so
 * throwing on an unhandled event type produces an infinite redelivery loop.
 */
export function normaliseMessageEvent(payload: unknown): NormalisedMessage | null {
  const parsed = FeishuMessageEvent.safeParse(payload);
  if (!parsed.success) return null;

  const { header, event } = parsed.data;
  const eventType = header?.event_type ?? payloadType(payload);
  if (eventType !== 'im.message.receive_v1') return null;

  // A bot replying to itself is the classic infinite loop in a group chat.
  if (event.sender.sender_type === 'app') return null;
  if (event.message.message_type !== 'text' && event.message.message_type !== 'post') return null;

  const senderOpenId = event.sender.sender_id?.open_id ?? undefined;
  if (senderOpenId === undefined) return null;

  const parsedText = extractText(event.message.content, event.message.message_type);
  if (parsedText === null) return null;
  let text = parsedText;

  // Mention placeholders look like `@_user_1`. Strip them, but remember whether
  // there were any: in a group, an unaddressed message is not ours to answer.
  const mentions = event.message.mentions ?? [];
  const hadMention = mentions.length > 0;
  for (const mention of mentions) {
    text = text.split(mention.key).join('');
  }
  text = text.replace(/\s+/g, ' ').trim();
  if (text.length === 0) return null;

  const mentionedOpenIds = mentions
    .map((mention) =>
      typeof mention.id === 'string' ? mention.id : mention.id?.open_id,
    )
    .filter((id): id is string => typeof id === 'string' && id.length > 0);
  const mentionedNames = mentions
    .map((mention) => mention.name)
    .filter((name): name is string => typeof name === 'string' && name.length > 0);

  return {
    eventId: header?.event_id ?? event.message.message_id,
    messageId: event.message.message_id,
    chatId: event.message.chat_id,
    chatType: event.message.chat_type,
    senderOpenId,
    text,
    // In a 1:1 chat every message is addressed to the bot.
    addressedToBot: event.message.chat_type === 'p2p' || hadMention,
    mentionedOpenIds,
    mentionedNames,
  };
}

function extractText(
  content: string | Record<string, unknown>,
  messageType: string,
): string | null {
  let parsed: unknown;
  if (typeof content === 'string') {
    try {
      parsed = JSON.parse(content);
    } catch {
      return null;
    }
  } else {
    parsed = content;
  }

  if (messageType === 'text') {
    if (typeof parsed === 'object' && parsed !== null) {
      const text = (parsed as { text?: unknown }).text;
      if (typeof text === 'string') return text;
    }
    return null;
  }

  if (messageType === 'post') {
    // Feishu rich text: { title, content: [[{tag:'text', text:'...'}, {tag:'at', user_id:'...'}]] }
    const out: string[] = [];
    const visit = (value: unknown): void => {
      if (typeof value === 'string') return;
      if (Array.isArray(value)) {
        for (const item of value) visit(item);
        return;
      }
      if (typeof value !== 'object' || value === null) return;
      const record = value as Record<string, unknown>;
      if (typeof record['title'] === 'string') out.push(record['title']);
      if (typeof record['text'] === 'string') out.push(record['text']);
      if (Array.isArray(record['content'])) visit(record['content']);
    };
    visit(parsed);
    const text = out.join(' ').replace(/\s+/g, ' ').trim();
    return text.length > 0 ? text : null;
  }

  return null;
}

function payloadType(payload: unknown): string | undefined {
  if (typeof payload !== 'object' || payload === null) return undefined;
  const event = (payload as { event?: { type?: unknown } }).event;
  return typeof event?.type === 'string' ? event.type : undefined;
}

import { createHash, timingSafeEqual, createDecipheriv } from 'node:crypto';

/**
 * Feishu event-subscription verification.
 *
 * Two independent things happen before a Feishu event can be trusted, and they are
 * easy to conflate:
 *
 *   1. An `encrypt_key` may encrypt the whole body (AES-256-CBC, key derived by
 *      SHA-256 of the key string, IV = first 16 bytes of the ciphertext).
 *   2. A `verification_token` appears *inside* the payload and must match ours.
 *
 * Doing only the token check would let anyone who has seen one valid request
 * replay/forge a body; doing only decryption would accept any well-encrypted
 * garbage. Both are required, and both fail closed.
 */
export interface FeishuCryptoConfig {
  verificationToken: string;
  /** Optional. When set, the body is expected to be `{ encrypt: "..." }`. */
  encryptKey?: string;
}

export class FeishuVerificationError extends Error {
  override name = 'FeishuVerificationError';
}

/** Decrypt a `{encrypt: "..."}` envelope. Throws FeishuVerificationError on any failure. */
export function decryptEnvelope(envelope: { encrypt: string }, encryptKey: string): string {
  let key: Buffer;
  try {
    key = createHash('sha256').update(encryptKey, 'utf8').digest();
  } catch {
    throw new FeishuVerificationError('Could not derive the encryption key.');
  }

  const raw = Buffer.from(envelope.encrypt, 'base64');
  // AES-CBC needs at least one full IV block plus one byte of payload.
  if (raw.length <= 16) throw new FeishuVerificationError('Encrypted payload is too short.');

  const iv = raw.subarray(0, 16);
  const ciphertext = raw.subarray(16);

  try {
    const decipher = createDecipheriv('aes-256-cbc', key, iv);
    // Feishu pads with PKCS#7; node handles it unless the payload is corrupt.
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf8');
  } catch {
    throw new FeishuVerificationError('Could not decrypt the payload — wrong encrypt key?');
  }
}

/**
 * Constant-time comparison. A plain `===` on a shared secret leaks its prefix
 * length through timing, which is a real attack against a public webhook.
 */
function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

export type FeishuBody = Record<string, unknown>;

/**
 * Verify a raw request body and return the parsed event payload.
 *
 * Returns the *decoded* object, not the envelope: callers should never have to
 * remember which form they are holding. Handles both the url_verification
 * handshake (which carries a token but no encryption) and real events.
 */
export function parseFeishuBody(rawBody: string, config: FeishuCryptoConfig): FeishuBody {
  let parsed: FeishuBody;
  try {
    parsed = JSON.parse(rawBody) as FeishuBody;
  } catch {
    throw new FeishuVerificationError('Body is not valid JSON.');
  }

  let payload = parsed;
  if (typeof parsed['encrypt'] === 'string') {
    if (config.encryptKey === undefined) {
      throw new FeishuVerificationError('Body is encrypted but no encrypt key is configured.');
    }
    const decrypted = decryptEnvelope({ encrypt: parsed['encrypt'] }, config.encryptKey);
    try {
      payload = JSON.parse(decrypted) as FeishuBody;
    } catch {
      throw new FeishuVerificationError('Decrypted payload is not valid JSON.');
    }
  }

  const token = payload['token'] ?? (payload['header'] as { token?: string } | undefined)?.token;
  if (typeof token !== 'string' || !safeEqual(token, config.verificationToken)) {
    throw new FeishuVerificationError('Verification token mismatch.');
  }

  return payload;
}

/**
 * The handshake Feishu performs once, when the subscription URL is saved. Separate
 * from real events because it must be answered synchronously with a specific body,
 * before any agent work exists.
 */
export function urlVerificationChallenge(payload: FeishuBody): string | null {
  if (payload['type'] !== 'url_verification') return null;
  const challenge = payload['challenge'];
  return typeof challenge === 'string' ? challenge : null;
}

/**
 * Main agent gateway.
 *
 * Two transports, one handler:
 *   - `FEISHU_EVENT_MODE=ws`   long connection (default; no public URL needed)
 *   - `FEISHU_EVENT_MODE=http` webhook at POST /events
 *
 * The gateway owns verification, idempotency, queueing, and delivery. The
 * consulting logic lives in `@mas/consult`, so the same agent can be reused by
 * the workbench or a CLI without reimplementation.
 */
import { MainConsultAgent } from '@mas/consult';
import { loadConfig } from './config.js';
import { createLogger } from './logger.js';
import { LarkGatewayClient } from './feishu/client.js';
import type { BotIdentity } from './feishu/client.js';
import { MainAgentHandler } from './handler.js';
import { startHttpServer } from './http.js';
import { startWebSocket, type WebSocketHandle } from './ws.js';
import type { Server } from 'node:http';

async function main(): Promise<void> {
  const config = loadConfig();
  const logger = createLogger(config.logLevel, { app: 'main-agent-gateway' });

  const client = new LarkGatewayClient(
    config,
    process.env['FEISHU_OPEN_BASE_URL'] ?? 'https://open.feishu.cn',
  );

  let identity: BotIdentity = {
    ...(config.botOpenId !== undefined ? { openId: config.botOpenId } : {}),
    name: config.botName,
  };

  try {
    const fetched = await client.getBotIdentity();
    identity = {
      ...(fetched.openId !== undefined ? { openId: fetched.openId } : {}),
      name: fetched.name ?? config.botName,
    };
    logger.info('bot identity resolved', { openId: identity.openId, name: identity.name });
  } catch (cause) {
    logger.warn('could not resolve bot identity; mention matching falls back to names', {
      error: cause instanceof Error ? cause.message : String(cause),
    });
  }

  const agent = MainConsultAgent.fromRepo({
    root: config.knowledgeRoot,
    maxChars: config.maxAnswerChars,
    ...(config.sourcesPath !== undefined ? { sourcesPath: config.sourcesPath } : {}),
  });

  const handler = new MainAgentHandler({
    config,
    client,
    agent,
    identity,
    logger,
  });

  logger.info('main agent ready', {
    mode: config.mode,
    appId: config.appId,
    knowledgeChunks: agent.corpus.chunks.length,
    groupMode: config.groupMode,
    messageFormat: config.messageFormat,
    llm: process.env['MAIN_AGENT_LLM'] ?? 'auto',
  });

  let ws: WebSocketHandle | undefined;
  let server: Server | undefined;

  if (config.mode === 'ws') {
    ws = await startWebSocket(handler, config, logger);
    logger.info('websocket status', { status: ws.status() });
  } else {
    server = await startHttpServer(handler, config, logger);
  }

  let stopping = false;
  const shutdown = async (signal: string): Promise<void> => {
    if (stopping) return;
    stopping = true;
    logger.info('shutting down', { signal });
    ws?.close();
    if (server !== undefined) {
      await new Promise<void>((resolve) => server?.close(() => resolve()));
    }
    await handler.drain();
    logger.info('shutdown complete', { stats: handler.stats() });
    process.exit(0);
  };

  process.on('SIGINT', () => void shutdown('SIGINT'));
  process.on('SIGTERM', () => void shutdown('SIGTERM'));
  process.on('unhandledRejection', (reason) => {
    logger.error('unhandled rejection', {
      error: reason instanceof Error ? reason.message : String(reason),
    });
  });
  process.on('uncaughtException', (error) => {
    logger.error('uncaught exception', { error: error.message });
  });

  // Keep the process alive even if the transport is reconnecting and no server is
  // listening. A gateway that exits silently is worse than one that logs an error.
  await new Promise<void>(() => {});
}

void main().catch((cause: unknown) => {
  console.error(
    JSON.stringify({
      ts: new Date().toISOString(),
      level: 'error',
      msg: 'fatal startup error',
      error: cause instanceof Error ? cause.message : String(cause),
    }),
  );
  process.exit(1);
});

import {
  query,
  type Options,
  type SDKMessage,
  type SDKUserMessage,
} from '@anthropic-ai/claude-agent-sdk';
import type { RunStatus, RunStep, RunTrigger } from '@mas/shared';
import { createStepRecorder, type StepRecorder } from './tools/result.js';

/**
 * The agent runtime is one file on purpose. Everything an agent product needs to
 * get right - budget, cancellation, attribution, structured output - happens in
 * *one* loop, and splitting that loop across modules is how the budget check ends
 * up not running on the path that matters.
 */

export interface AgentRunRequest {
  /** The user's actual ask. For a Feishu message this is the message text. */
  prompt: string;
  /** Which workflow this run executes. Versioned so old runs stay interpretable. */
  workflow: { name: string; version: string };
  trigger: RunTrigger;
  /** Brand scope. Every tool call inherits it. */
  brandId: string;
  actor?: { kind: 'user' | 'feishu-user' | 'system'; id: string; displayName?: string };
}

export interface AgentRunResult {
  status: RunStatus;
  /** Present only on success. */
  output?: string;
  steps: RunStep[];
  usage: { inputTokens: number; outputTokens: number; costUsd: number };
  /** Why the run stopped. Always populated on a terminal status. */
  outcome: { reason: string; retryable: boolean };
  /** SDK session id, so a human can resume the conversation later. */
  sessionId?: string;
  /** Set by `createRuntime` once the run has been recorded in the RunStore. */
  runId?: string;
}

export interface RunAgentOptions {
  model: string;
  maxCostUsd: number;
  maxTurns: number;
  systemPrompt: string;
  /** MCP servers to expose, keyed by the name their tool prefixes use. */
  mcpServers: NonNullable<Options['mcpServers']>;
  /** Fully-qualified tool names the run may call without a permission prompt. */
  allowedTools: string[];
  cwd: string;
}

/**
 * One turn of input, as an async iterable so the run can later be upgraded to
 * multi-turn without changing the call site.
 */
async function* singleTurn(prompt: string): AsyncGenerator<SDKUserMessage> {
  yield {
    type: 'user',
    message: { role: 'user', content: prompt },
    parent_tool_use_id: null,
  };
}

function truncate(text: string, max = 2000): string {
  return text.length <= max ? text : `${text.slice(0, max)}... [${text.length - max} chars truncated]`;
}

/**
 * Maps one SDK message to zero or more displayable steps.
 *
 * Kept pure and exported so it can be unit-tested against captured transcripts:
 * this mapping is where observability bugs hide, and they stay invisible in
 * production until someone cannot explain a failed run.
 */
export function messageToSteps(msg: SDKMessage, recorder: StepRecorder): void {
  switch (msg.type) {
    case 'assistant': {
      const content = msg.message.content;
      if (!Array.isArray(content)) break;
      for (const block of content) {
        if (block.type === 'text' && block.text.trim().length > 0) {
          recorder.record({ kind: 'assistant-text', summary: truncate(block.text) });
        } else if (block.type === 'tool_use') {
          recorder.record({
            kind: 'tool-call',
            tool: block.name,
            summary: truncate(JSON.stringify(block.input)),
          });
        }
      }
      break;
    }
    case 'user': {
      // Tool results come back as user messages. Render them so the timeline reads
      // as a conversation rather than a list of mysterious tool names.
      const content = msg.message.content;
      if (!Array.isArray(content)) break;
      for (const block of content) {
        if (typeof block !== 'object' || block === null || !('type' in block)) continue;
        if (block.type !== 'tool_result') continue;
        const raw = block.content;
        const text =
          typeof raw === 'string'
            ? raw
            : Array.isArray(raw)
              ? raw
                  .map((c) => ('text' in c && typeof c.text === 'string' ? c.text : ''))
                  .join('\n')
              : '';
        recorder.record({ kind: 'tool-result', summary: truncate(text) });
      }
      break;
    }
    default:
      break;
  }
}

export async function runAgent(
  req: AgentRunRequest,
  opts: RunAgentOptions,
  deps: { signal?: AbortSignal } = {},
): Promise<AgentRunResult> {
  const recorder = createStepRecorder();
  const abort = new AbortController();
  const onOuterAbort = () => abort.abort();
  deps.signal?.addEventListener('abort', onOuterAbort, { once: true });

  const q = query({
    prompt: singleTurn(req.prompt),
    options: {
      model: opts.model,
      maxTurns: opts.maxTurns,
      // Defence in depth: the SDK enforces this too, but a run that trips the SDK
      // limit still pays for the turn that crossed it. Our own check below stops earlier.
      maxBudgetUsd: opts.maxCostUsd,
      systemPrompt: { type: 'custom', prompt: opts.systemPrompt },
      mcpServers: opts.mcpServers,
      allowedTools: opts.allowedTools,
      /**
       * `dontAsk` rather than `bypassPermissions`: tools that are not on the
       * allow-list are denied outright instead of prompting. A headless bot has
       * nobody to prompt, and a silent hang is worse than a clean denial.
       */
      permissionMode: 'dontAsk',
      // The SDK default is `[]`, meaning no CLAUDE.md and no project settings are
      // loaded. That is what we want here: the workflow prompt is the whole brief,
      // and ambient repo config leaking into a customer-facing bot is a hazard.
      settingSources: [],
      cwd: opts.cwd,
      abortController: abort,
    },
  });

  let output = '';
  let sessionId: string | undefined;
  let costUsd = 0;
  let status: RunStatus = 'running';
  let outcome: { reason: string; retryable: boolean } | undefined;
  const usage = { inputTokens: 0, outputTokens: 0, costUsd: 0 };

  try {
    for await (const msg of q) {
      messageToSteps(msg, recorder);

      if (msg.type === 'system' && msg.subtype === 'init') {
        sessionId = msg.session_id;
      }

      if (msg.type === 'result') {
        sessionId ??= msg.session_id;
        costUsd = msg.total_cost_usd;
        // `usage` on the result is main-loop-only; `modelUsage` is the cumulative,
        // per-model truth (it includes subagents and compaction). Accounting reads
        // modelUsage, exactly as the SDK docs instruct.
        for (const m of Object.values(msg.modelUsage)) {
          usage.inputTokens += m.inputTokens + m.cacheReadInputTokens + m.cacheCreationInputTokens;
          usage.outputTokens += m.outputTokens;
        }
        usage.costUsd = costUsd;

        if (msg.subtype === 'success') {
          status = 'succeeded';
          output = msg.result;
          outcome = { reason: 'Workflow completed.', retryable: false };
        } else {
          status = msg.subtype === 'error_max_budget_usd' ? 'budget-exceeded' : 'failed';
          outcome = {
            reason: `${msg.subtype}: ${msg.errors.join('; ') || 'no detail returned'}`,
            retryable:
              msg.subtype === 'error_max_turns' || msg.subtype === 'error_during_execution',
          };
          recorder.record({ kind: 'error', summary: outcome.reason });
        }
      }

      // Stop as soon as spend crosses the ceiling, even if the SDK has not yet
      // emitted its own budget result. Without this, a run that is one expensive
      // turn away from the limit still pays for that turn.
      if (costUsd > opts.maxCostUsd && status === 'running') {
        await q.interrupt();
        status = 'budget-exceeded';
        outcome = {
          reason: `Cost ceiling reached: $${costUsd.toFixed(4)} > $${opts.maxCostUsd.toFixed(4)}.`,
          retryable: true,
        };
      }
    }
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : String(cause);
    status = abort.signal.aborted ? 'cancelled' : 'failed';
    outcome = {
      reason: abort.signal.aborted ? 'Run cancelled by caller.' : `Runtime threw: ${message}`,
      retryable: !abort.signal.aborted,
    };
    recorder.record({ kind: 'error', summary: outcome.reason });
  } finally {
    deps.signal?.removeEventListener('abort', onOuterAbort);
  }

  return {
    status,
    ...(status === 'succeeded' ? { output } : {}),
    steps: recorder.all(),
    usage,
    outcome: outcome ?? { reason: 'Run ended without a result message.', retryable: true },
    ...(sessionId !== undefined ? { sessionId } : {}),
  };
}

import { tool } from '@anthropic-ai/claude-agent-sdk';
import { z } from 'zod';
import type { BrandProfile, Recipe } from '@mas/shared';
import { err, guard, ok, toCallToolResult } from './result.js';

/**
 * Tools are defined against *ports* - small interfaces describing what the agent
 * needs - rather than against a database client. That inversion is what makes
 * the agent testable without a live Feishu tenant or a populated DB: evals wire
 * in fakes, production wires in the real thing, and the tool's prompt-visible
 * contract is identical in both.
 */
export interface BrandStore {
  get(brandId: string): Promise<BrandProfile | null>;
  listForUser(userId: string): Promise<BrandProfile[]>;
}

export interface ReferenceStore {
  save(
    brandId: string,
    input: {
      url: string;
      platformVideoId?: string;
      /** Raw engagement counts. Optional fields, not a loose record: the shape is the contract. */
      metrics?: {
        views?: number | undefined;
        likes?: number | undefined;
        comments?: number | undefined;
        shares?: number | undefined;
      };
    },
  ): Promise<{ referenceId: string }>;
  list(brandId: string): Promise<{ referenceId: string; url: string; analysed: boolean }[]>;
  /** Analysis is the durable artifact; the source video is never stored (ADR 0006). */
  saveAnalysis(brandId: string, referenceId: string, analysis: unknown): Promise<void>;
  getAnalysis(brandId: string, referenceId: string): Promise<unknown | null>;
}

export interface VisionAnalyzer {
  /** Returns a *validated* ReferenceAnalysis or throws; the tool converts throws to errors. */
  analyze(input: { url: string; brandContext: string }): Promise<unknown>;
}

export interface RecipeStore {
  saveDraft(input: {
    brandId: string;
    referenceId: string;
    recipe: unknown;
  }): Promise<{ recipeId: string }>;
  getRecipe(brandId: string, recipeId: string): Promise<unknown | null>;
  /** Newest first; scoped by brand (ADR 0009). */
  listRecipes(brandId: string, limit?: number): Promise<Recipe[]>;
}

export interface ToolDeps {
  brands: BrandStore;
  references: ReferenceStore;
  vision: VisionAnalyzer;
  recipes: RecipeStore;
  /** Scoped to the run: every tool call is attributable to a brand and an actor. */
  scope: { brandId: string; actorId: string };
}

/**
 * The toolset is the product's real surface area. An agent is only as good as
 * the verbs you give it, so this list is kept short and each entry is a decision:
 * anything the model could infer on its own is deliberately absent.
 */
export function createBrandTools(deps: ToolDeps) {
  const getBrandProfile = tool(
    'get_brand_profile',
    [
      'Load the brand profile for the current brand: voice, audience, market, guardrails, and success criteria.',
      'Call this FIRST, before analysing any reference video or writing anything. Every later decision depends on',
      'the guardrails it returns, and skipping it is how an agent produces an on-brand-sounding post that breaks a',
      'regulated-claims rule.',
    ].join(' '),
    {},
    async () =>
      toCallToolResult(
        await guard(async () => {
          const brand = await deps.brands.get(deps.scope.brandId);
          if (!brand) return err(`No brand profile found for ${deps.scope.brandId}.`, false);
          return ok(JSON.stringify(brand), { brand: brand as unknown as Record<string, unknown> });
        }),
      ),
    { annotations: { readOnlyHint: true } },
  );

  const saveReference = tool(
    'save_reference_video',
    [
      'Record a TikTok video as a reference for the current brand, without analysing it.',
      'Use this when the user pastes a link but you are not ready to analyse - for example when they paste five',
      'links at once and you want to confirm the list before spending analysis budget on each.',
    ].join(' '),
    {
      url: z.string().url().describe('The full TikTok video URL.'),
      platformVideoId: z
        .string()
        .optional()
        .describe('The numeric video id parsed from the URL, when you can see it.'),
      metrics: z
        .object({
          views: z.number().int().nonnegative().optional(),
          likes: z.number().int().nonnegative().optional(),
          comments: z.number().int().nonnegative().optional(),
          shares: z.number().int().nonnegative().optional(),
        })
        .optional()
        .describe(
          'Engagement numbers if the user or a scrape provided them. Omit rather than guessing.',
        ),
    },
    async (args) =>
      toCallToolResult(
        await guard(async () => {
          const saved = await deps.references.save(deps.scope.brandId, {
            url: args.url,
            ...(args.platformVideoId ? { platformVideoId: args.platformVideoId } : {}),
            ...(args.metrics ? { metrics: args.metrics } : {}),
          });
          return ok(`Saved reference ${saved.referenceId}.`, { referenceId: saved.referenceId });
        }),
      ),
    { annotations: { readOnlyHint: false } },
  );

  const listReferences = tool(
    'list_reference_videos',
    'List the reference videos already saved for the current brand, and whether each has been analysed.',
    {},
    async () =>
      toCallToolResult(
        await guard(async () => {
          const rows = await deps.references.list(deps.scope.brandId);
          if (rows.length === 0) return ok('No reference videos saved for this brand yet.');
          const text = rows
            .map((r) => `- ${r.referenceId} ${r.url} ${r.analysed ? '(analysed)' : '(not analysed)'}`)
            .join('\n');
          return ok(text, { references: rows as unknown as Record<string, unknown> });
        }),
      ),
    { annotations: { readOnlyHint: true } },
  );

  const analyzeReference = tool(
    'analyze_reference_video',
    [
      'Analyse a saved TikTok reference video and persist a structured breakdown: hook pattern, beat skeleton,',
      'shot list, voiceover, audio rights, caption formula, and how transferable it is to this brand.',
      'Call this before writing a recipe - the recipe writer is not allowed to invent an analysis.',
      'The result is cached on the reference; calling it twice costs money but returns the same shape.',
    ].join(' '),
    {
      referenceId: z
        .string()
        .min(1)
        .describe('A reference id previously returned by save_reference_video.'),
      brandContext: z
        .string()
        .min(1)
        .describe(
          'One or two sentences on what this brand sells and who watches it. Passed to the analyser so ' +
            'it can judge transferability; do not paste the whole brand profile here.',
        ),
    },
    async (args) =>
      toCallToolResult(
        await guard(async () => {
          const references = await deps.references.list(deps.scope.brandId);
          const found = references.find((r) => r.referenceId === args.referenceId);
          if (!found) {
            return err(
              `No reference ${args.referenceId} for this brand. Call list_reference_videos to see valid ids.`,
              false,
            );
          }
          // The analyser is the only component allowed to produce a ReferenceAnalysis,
          // and it validates before returning. A malformed analysis must not reach the
          // recipe writer, where it would silently become a bad script.
          const analysis = await deps.vision.analyze({
            url: found.url,
            brandContext: args.brandContext,
          });
          return ok(JSON.stringify(analysis), { analysis: analysis as Record<string, unknown> });
        }),
      ),
    { annotations: { readOnlyHint: false }, alwaysLoad: true },
  );

  const saveRecipeDraft = tool(
    'save_recipe_draft',
    [
      'Persist a draft recipe for human review. This is the deliverable of the whole workflow.',
      'A recipe is the cloneable abstraction of the reference video, re-skinned for this brand: hook, beats,',
      'caption, hashtags, and audio direction. Do not call this until analyze_reference_video has returned,',
      'and do not mark anything as reviewed or approved - only a human can do that.',
    ].join(' '),
    {
      referenceId: z.string().min(1),
      title: z
        .string()
        .min(1)
        .max(120)
        .describe('Internal working title, e.g. "August launch - result-first hook".'),
      abstractionDistance: z
        .number()
        .min(0)
        .max(1)
        .describe(
          'How far this strays from the reference: 0 means a near-literal copy, 1 means only the abstract ' +
            'pattern survived. Above 0.9, expect a reviewer to ask whether the reference still matters.',
        ),
      exclusions: z
        .array(
          z.object({
            element: z.string().min(1).describe('Something from the reference you deliberately left out.'),
            reason: z.string().min(1).describe('Why. Rights, brand fit, audience mismatch - be specific.'),
          }),
        )
        .default([])
        .describe('Elements dropped from the reference and why. Reviewers read this first.'),
      hook: z.object({
        text: z.string().min(1).describe('The spoken/opening line, at most ~2 seconds of speech.'),
        onScreenText: z.string().optional(),
        durationSec: z.number().positive().max(5),
        pattern: z
          .string()
          .min(1)
          .describe('The hook pattern reused from the analysis, e.g. "curiosity-gap".'),
      }),
      beats: z
        .array(
          z.object({
            kind: z.enum([
              'hook',
              'context',
              'problem',
              'mechanism',
              'proof',
              'objection-handling',
              'cta',
            ]),
            durationSec: z.number().positive(),
            script: z.string().min(1).describe('What is said. Write it as it will be spoken.'),
            translation: z
              .string()
              .optional()
              .describe('Translation, only when the spoken language differs from the primary market locale.'),
            visual: z
              .string()
              .min(1)
              .describe('What the camera sees. A shooter must be able to act on this.'),
            onScreenText: z.string().optional(),
            derivedFromShotIndex: z.number().int().nonnegative().optional(),
          }),
        )
        .min(2)
        .describe('Ordered beats. Together with the hook they should land in the 15-45s window.'),
      caption: z.string().min(1).max(2200),
      hashtags: z.array(z.string()).default([]),
      audio: z.object({
        direction: z
          .string()
          .min(1)
          .describe('What audio should play, and why that choice serves the video.'),
        rights: z.enum(['original', 'platform-library', 'licensed', 'unknown']),
      }),
      selfCheck: z
        .object({
          brandVoiceMatch: z.number().min(0).max(1),
          hookStrength: z.number().min(0).max(1),
          claimsSubstantiated: z
            .boolean()
            .describe(
              'True only if every factual claim in the script traces to something the brand can prove.',
            ),
          notes: z.string().optional(),
        })
        .optional()
        .describe(
          'Your own assessment. It is recorded, not trusted - an eval gate decides whether this ships.',
        ),
    },
    async (args) =>
      toCallToolResult(
        await guard(async () => {
          const saved = await deps.recipes.saveDraft({
            brandId: deps.scope.brandId,
            referenceId: args.referenceId,
            recipe: args,
          });
          return ok(`Saved recipe draft ${saved.recipeId} for review.`, {
            recipeId: saved.recipeId,
          });
        }),
      ),
    { alwaysLoad: true },
  );

  return [getBrandProfile, saveReference, listReferences, analyzeReference, saveRecipeDraft];
}

/**
 * Names the runtime must allow. Derived rather than hand-listed: a tool added
 * above without a corresponding permission entry is a silent no-op, which is the
 * hardest class of agent bug to notice.
 */
export function brandToolNames(serverName = 'brand'): string[] {
  return [
    'get_brand_profile',
    'save_reference_video',
    'list_reference_videos',
    'analyze_reference_video',
    'save_recipe_draft',
  ].map((name) => `mcp__${serverName}__${name}`);
}

import type { RunStep } from '@mas/shared';

/**
 * A tool result is data, never an exception.
 *
 * The Agent SDK keeps the loop alive when a tool returns `isError: true`, and
 * kills the whole run when a handler throws. Since almost every failure here is
 * *expected* (a TikTok URL that 404s, a brand with no guardrails configured),
 * the tool layer treats throwing as a bug. This module gives that policy one
 * shape so every tool agrees.
 */
export type ToolOk = {
  ok: true;
  /** Human/agent-readable summary. This string goes back into the model's context. */
  text: string;
  /** Machine-readable payload for the workbench and for eval assertions. */
  data?: Record<string, unknown>;
};

export type ToolErr = {
  ok: false;
  text: string;
  /**
   * Whether the agent should try a different approach. `false` means the input
   * itself was wrong and retrying verbatim will fail the same way.
   */
  retryable: boolean;
};

export type ToolOutcome = ToolOk | ToolErr;

/** Convenience constructor so tool bodies read as a value, not as control flow. */
export function ok(text: string, data?: Record<string, unknown>): ToolOk {
  return data === undefined ? { ok: true, text } : { ok: true, text, data };
}

export function err(text: string, retryable = true): ToolErr {
  return { ok: false, text, retryable };
}

/**
 * Adapter to the MCP result shape the SDK expects. Deliberately does not throw:
 * an unexpected exception inside a tool becomes a non-retryable error the agent
 * can see, which is strictly more useful than a dead run.
 */
export function toCallToolResult(outcome: ToolOutcome): {
  content: { type: 'text'; text: string }[];
  structuredContent?: Record<string, unknown>;
  isError: boolean;
} {
  if (outcome.ok) {
    return outcome.data === undefined
      ? { content: [{ type: 'text', text: outcome.text }], isError: false }
      : {
          content: [{ type: 'text', text: outcome.text }],
          structuredContent: outcome.data,
          isError: false,
        };
  }
  return { content: [{ type: 'text', text: outcome.text }], isError: true };
}

/** Wrap a tool body so a thrown Error becomes a visible, non-fatal tool error. */
export async function guard(fn: () => Promise<ToolOutcome>): Promise<ToolOutcome> {
  try {
    return await fn();
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : String(cause);
    return err(`Tool crashed: ${message}`, false);
  }
}

/**
 * Steps are what the workbench renders and what cost accounting walks over, so
 * their construction is centralised: a step missing a timestamp or a token
 * count is an observability hole, not a cosmetic issue.
 */
export interface StepRecorder {
  record(step: Omit<RunStep, 'index' | 'at'>): RunStep;
  all(): RunStep[];
}

export function createStepRecorder(now: () => Date = () => new Date()): StepRecorder {
  const steps: RunStep[] = [];
  return {
    record(step) {
      const full: RunStep = { ...step, index: steps.length, at: now().toISOString() };
      steps.push(full);
      return full;
    },
    all: () => [...steps],
  };
}
